var q = String(s || "").trim();
if (!q) return [];
var landing = String(basicUrl || "https://mm.btlm.in").replace(/\/+$/, "");
var ua = "Mozilla/5.0 (Linux; Android 16) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/128.0 Mobile Safari/537.36";

function cleanText(v) {
    return String(v || "")
        .replace(/<script[\s\S]*?<\/script>/gi, "")
        .replace(/<style[\s\S]*?<\/style>/gi, "")
        .replace(/<[^>]+>/g, "")
        .replace(/&nbsp;/gi, " " )
        .replace(/&amp;/gi, "&")
        .replace(/&lt;/gi, "<")
        .replace(/&gt;/gi, ">")
        .replace(/&#39;/gi, "'")
        .replace(/&quot;/gi, "\"")
        .replace(/&#(\d+);/g, function(_, n){ try { return String.fromCharCode(Number(n)); } catch(e) { return _; } })
        .replace(/\s+/g, " " )
        .trim();
}
function attr(tag, name) {
    var re = new RegExp(name + "\\s*=\\s*[\"']([^\"']*)[\"']", "i");
    var m = String(tag || "").match(re);
    return m ? m[1] : "";
}
function abs(base, href) {
    href = String(href || "").replace(/&amp;/g, "&").trim();
    if (!href) return "";
    if (/^https?:\/\//i.test(href)) return href;
    if (/^\/\//.test(href)) return "https:" + href;
    var om = String(base || "").match(/^(https?:\/\/[^\/]+)/i);
    var origin = om ? om[1] : String(base || "");
    if (href.charAt(0) === "/") return origin + href;
    var dir = String(base || "").replace(/[?#].*$/, "").replace(/\/[^\/]*$/, "/");
    return dir + href;
}
function sizeToBytes(text) {
    var m = cleanText(text).match(/([0-9.]+)\s*(TB|GB|MB|KB|B)/i);
    if (!m) return 0;
    var n = Number(m[1] || 0), u = String(m[2] || "B").toUpperCase();
    var pow = {B:0,KB:1,MB:2,GB:3,TB:4}[u] || 0;
    return Math.round(n * Math.pow(1024, pow));
}
function hashFrom(v) {
    v = String(v || "");
    var m = v.match(/btih:([A-Fa-f0-9]{40}|[A-Za-z2-7]{32})/i);
    if (!m) m = v.match(/(?:^|[\/\.\?&=_:#@!%+-])([A-Fa-f0-9]{40})(?![A-Za-z0-9])/);
    if (!m) m = v.match(/(?:^|\/)([A-Za-z2-7]{32})(?:$|[\/?#&])/);
    return m ? String(m[1]).toUpperCase() : "";
}
function magnet(hash, title) {
    if (!hash) return "";
    var u = "magnet:?xt=urn:btih:" + hash;
    if (title) u += "&dn=" + encodeURIComponent(title);
    return u;
}
function headers(ref) {
    return {
        "User-Agent": ua,
        "Accept": "text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8",
        "Accept-Language": "zh-CN,zh;q=0.9,en;q=0.6",
        "Referer": ref || landing + "/"
    };
}
function fetchHtml(url, ref) {
    return String(fetch(url, {headers: headers(ref), timeout: 12000}) || "");
}
function addUnique(arr, seen, v) {
    v = String(v || "").replace(/\/+$/, "");
    if (!/^https?:\/\//i.test(v) || seen[v]) return;
    seen[v] = 1; arr.push(v);
}
function discoverBases() {
    var out = [], seen = {};
    addUnique(out, seen, landing);
    try {
        var h = fetchHtml(landing + "/", landing + "/");
        var am, are = /<a\b[^>]*href\s*=\s*[\"']([^\"']+)[\"'][^>]*>([\s\S]*?)<\/a>/gi;
        while ((am = are.exec(h)) !== null) {
            var href = abs(landing + "/", am[1]);
            var txt = cleanText(am[2]);
            if (/btlm/i.test(href)) addUnique(out, seen, href.replace(/\/[^\/]*$/, ""));
            var tm = txt.match(/https?:\/\/[^\s<]+/i);
            if (tm && /btlm/i.test(tm[0])) addUnique(out, seen, tm[0]);
        }
        var all = h.match(/https?:\/\/[A-Za-z0-9.-]*btlm[A-Za-z0-9.-]*(?:\/[A-Za-z0-9._~:/?#\[\]@!$&'()*+,;=%-]*)?/gi) || [];
        for (var i = 0; i < all.length; i++) addUnique(out, seen, all[i].replace(/[\"'<>].*$/, ""));
    } catch (e) {}
    addUnique(out, seen, "https://run.btlm.info");
    addUnique(out, seen, "https://se.btlm.one");
    return out;
}
function discoverSearchRequests(base, home) {
    var reqs = [], seen = {};
    function add(url) {
        url = String(url || "");
        if (!url || seen[url]) return;
        seen[url] = 1; reqs.push(url);
    }
    var forms = String(home || "").match(/<form\b[\s\S]*?<\/form>/gi) || [];
    for (var i = 0; i < forms.length; i++) {
        var f = forms[i];
        if (!/search|搜索/i.test(f)) continue;
        var open = (f.match(/^<form\b[^>]*>/i) || [""])[0];
        var action = attr(open, "action") || "/search";
        var inputs = f.match(/<input\b[^>]*>/gi) || [];
        var name = "";
        for (var j = 0; j < inputs.length; j++) {
            var type = String(attr(inputs[j], "type") || "text").toLowerCase();
            var n = attr(inputs[j], "name");
            if (n && (type === "text" || type === "search" || /keyword|word|query|name|search|q/i.test(n))) { name = n; break; }
        }
        if (!name) name = "keyword";
        var u = abs(base + "/", action);
        u += (u.indexOf("?") >= 0 ? "&" : "?") + encodeURIComponent(name) + "=" + encodeURIComponent(q);
        if (p > 1) u += "&page=" + p;
        add(u);
    }
    var enc = encodeURIComponent(q);
    add(base + "/search?keyword=" + enc + (p > 1 ? "&page=" + p : ""));
    add(base + "/search?keyword=" + enc + (p > 1 ? "&p=" + p : ""));
    add(base + "/search?word=" + enc + (p > 1 ? "&page=" + p : ""));
    add(base + "/search?name=" + enc + (p > 1 ? "&page=" + p : ""));
    add(base + "/search?q=" + enc + (p > 1 ? "&page=" + p : ""));
    add(base + "/search/" + enc + (p > 1 ? "/" + p : ""));
    return reqs;
}
function parseResults(html, base) {
    var out = [], seen = {};
    html = String(html || "");
    var blocks = html.match(/<(?:li|tr|dd|article)\b[^>]*>[\s\S]*?<\/(?:li|tr|dd|article)>/gi) || [];
    if (!blocks.length) blocks = html.match(/<div\b[^>]*(?:class|id)=[\"'][^\"']*(?:result|search|item|torrent|list)[^\"']*[\"'][^>]*>[\s\S]*?<\/div>/gi) || [];
    if (!blocks.length) blocks = [html];
    for (var bi = 0; bi < blocks.length; bi++) {
        var block = blocks[bi];
        var anchors = block.match(/<a\b[^>]*>[\s\S]*?<\/a>/gi) || [];
        var bestTitle = "", bestHref = "", bestHash = "", detailHref = "";
        for (var ai = 0; ai < anchors.length; ai++) {
            var open = (anchors[ai].match(/^<a\b[^>]*>/i) || [""])[0];
            var href = attr(open, "href");
            var title = cleanText(anchors[ai]);
            var h = hashFrom(href);
            if (h) {
                if (!bestHash || title.length > bestTitle.length) { bestHash = h; bestHref = href; bestTitle = title; }
            } else if (/\/(?:detail|torrent|hash|info|show|bt|view)\b|[?&](?:hash|id)=/i.test(href)) {
                if (!detailHref || title.length > bestTitle.length) { detailHref = href; if (title) bestTitle = title; }
            } else if (!bestTitle && title.length > 3 && !/^(首页|登录|注册|下一页|上一页|更多)$/i.test(title)) {
                bestTitle = title;
            }
        }
        if (!bestHash) bestHash = hashFrom(block);
        var sizeM = cleanText(block).match(/([0-9.]+)\s*(TB|GB|MB|KB|B)/i);
        var dateM = cleanText(block).match(/(20\d{2}[-\/.]\d{1,2}[-\/.]\d{1,2}(?:\s+\d{1,2}:\d{1,2}(?::\d{1,2})?)?)/);
        if (bestHash) {
            var key = bestHash;
            if (seen[key]) continue;
            seen[key] = 1;
            out.push({title: bestTitle || bestHash, magnet: magnet(bestHash, bestTitle), bytes: sizeM ? sizeToBytes(sizeM[0]) : 0, seeders: -1, peers: -1, date: dateM ? dateM[1] : "", desc: sizeM ? sizeM[0] : ""});
        } else if (detailHref && bestTitle) {
            var du = abs(base + "/", detailHref);
            var dk = "URL:" + du;
            if (seen[dk]) continue;
            seen[dk] = 1;
            out.push({title: bestTitle, url: du, bytes: sizeM ? sizeToBytes(sizeM[0]) : 0, seeders: -1, peers: -1, date: dateM ? dateM[1] : "", desc: sizeM ? sizeM[0] : ""});
        }
    }
    return out;
}

var bases = discoverBases();
var errors = [];
for (var b = 0; b < bases.length; b++) {
    var base = bases[b];
    var home = "";
    try { home = fetchHtml(base + "/", landing + "/"); } catch (e0) {}
    var reqs = discoverSearchRequests(base, home);
    for (var ri = 0; ri < reqs.length; ri++) {
        try {
            var html = fetchHtml(reqs[ri], base + "/");
            if (/captcha|cloudflare|access denied|forbidden|recaptcha|challenge/i.test(html)) {
                errors.push(base + " 触发网页验证");
                continue;
            }
            var items = parseResults(html, base);
            if (items.length) return items;
            if (/没有|暂无|无结果|no result|not found/i.test(cleanText(html))) return [];
        } catch (e) {
            errors.push(base + "：" + (e.message || e));
        }
    }
}
throw new Error("BT联盟搜索失败" + (errors.length ? "；" + errors.slice(0, 4).join("；") : "；未识别当前搜索入口/结果结构"));

